-- Generated by scripts/import-remaining-monographs.py

WITH src (herb_slug, source, licence, attribution, url, claims, safety, doses, generation_method) AS (
  VALUES
  ('griffonia-simplicifolia', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=5htp&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Helps (to) promote healthy mood balance (Pöldinger et al. 1991; Zmilacher et al. 1988; Nakajima et al. 1978)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps (to) relieve sleep disturbances associated with mood imbalance (Sutanto et al. 2024; Poldinger et al. 1991; Soulairac and Lambinet 1988)"}, {"section": "Use(s) or Purpose(s)", "text": "Helps (to) relieve symptoms of fibromyalgia (Nicolodi and Sicuteri 1996; Sarzi Puttini and Caruso 1992; Caruso et al. 1990)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps (to) reduce the severity and duration of migraine headaches when taken as a preventative (prophylactic) (Titus et al. 1986; Bono et al. 1984; Sicuteri 1973)."}, {"section": "Use(s) or Purpose(s)", "text": "To be used with a program of reduced intake of dietary calories and increased physical activity (if possible) to help in weight management by reducing carbohydrate cravings (Cangiano et al.1998; Cangiano et al. 1992; Ceci et al. 1989)."}, {"section": "Use(s) or Purpose(s)", "text": "Restrictions when this monograph is combined with other monographs (Class II and III applications):"}, {"section": "Use(s) or Purpose(s)", "text": "If a weight management claim is made:"}, {"section": "Use(s) or Purpose(s)", "text": "Weight management is a long-term process and must therefore, be associated with a long-term intervention."}, {"section": "Use(s) or Purpose(s)", "text": "Medicinal ingredient with diuretic properties may be included in weight management products, however no diuretic claim can be applied as it is associated with a short-term duration of use (occasional use only)."}, {"section": "Use(s) or Purpose(s)", "text": "Stimulant laxatives cannot be present at therapeutic dose in weight management products as their short term duration of use is not compatible with the duration of use for weight management."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking carbidopa or health products with serotonergic activity such as mood balance supplements, cough medication containing dextromethorphan, pain killers or medications for nausea or migraine (Mayo Clinic Staff 2022; Patel and Marzella 2017; Turner et al 2006).", "When using this product exercise caution while driving or using machinery, as you may experience drowsiness (Berardi et al. 2002).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "All uses (excluding weight management)", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Weight management", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are breastfeeding.", "Healthy mood balance; Fibromyalgia symptoms", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have a psychological disorder such as anxiety or depression.", "Do not use if you have scleroderma (Lampert et al. 1992; Sternberg et al. 1980).", "Do not use if you are taking antidepressants (Mayo Clinic Staff 2022; Patel and Marzella 2017).", "Do not use if you are pregnant (HC 2010).", "When using this product you may experience gastrointestinal discomfort/disturbances (Turner et al. 2006; Byerley et al. 1987).", "Stop use and ask a health care practitioner/health care provider/health care professional/doctor/physician if you experience skin hardening, pain or stiffness of muscles or joints, tremors, agitation/confusion, or an increased heart rate (Boyer 2023; Varga 2023; Mayo Clinic Staff 2022; Patel and Marzella 2017; Das et al. 2004; Erner et al. 2003; Lampert et al. 1992; Sternberg et al. 1980)."]'::jsonb, '["Adults 18 years and older", "Healthy mood balance", "150 - 300 milligrams of 5-HTP, per day (Pöldinger et al. 1991; Nakajima et al. 1978).", "Fibromyalgia symptoms", "300 - 400 milligrams of 5-HTP, per day; Not to exceed 300 milligrams per single dose (Nicolodi and Sicuteri 1996; Caruso et al. 1990).", "Migraine prophylaxis", "200 - 600 milligrams of 5-HTP, per day; Not to exceed 300 milligrams per single dose (Titus et al. 1986; Sicuteri 1973).", "Weight management", "750 - 900 milligrams of 5-HTP, per day; Not to exceed 300 milligrams per single dose (Cangiano et al. 1998; Cangiano et al. 1992; Ceci et al. 1989).", "Sleep disturbances", "100 - 200 milligrams of 5-HTP, per day (Sutanto et al. 2024; Soulairac and Lambinet 1988; Soulairac and Lambinet 1977; Wyatt et al. 1971)."]'::jsonb, 'imported-ogl-canada'),
  ('medicago-sativa', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=alfalfa2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants (Raeeszadeh et al. 2022; Orak et al. 2021)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants that help fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (Raeeszadeh et al. 2022; Orak et al. 2021)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine as a nutritive tonic (BHP 1996; Meyer 1993)."}]'::jsonb, '["Products providing more than 900 mg of Alfalfa dried herb top/leaf, per day", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners, birth control medication or hormone therapy (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004).", "Do not use if you are pregnant or breastfeeding (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004).", "Do not use if you have a history of systemic lupus erythematosus (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004).", "No statement required."]'::jsonb, '["Adults 18 years and older", "Antioxidant", "Up to 30 grams of herb top/leaf, per day (BHP 1996; Mills 1985).", "Nutritive tonic", "9 - 30 grams of dried herb top/leaf, per day (BHP 1996; Mills 1985)."]'::jsonb, 'imported-ogl-canada'),
  ('aloe-vera', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=aloe.oral.orale2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "[(Traditionally) used in Herbal Medicine as a] stimulant laxative (Williamson 2003; Bradley 1992; Felter and Lloyd 1983; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine for the) short-term relief of occasional constipation (EMA 2016)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine to) promote(s) bowel movement (by direct action on the large intestine) (EMA 2016; Sweetman 2007; WHO 1999)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have a kidney disorder or a lazy bowel (EMA 2016; Gardner and McGuffin 2013; Brinker 2010).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2016; Gardner and McGuffin 2013; Brinker 2010).", "Do not use if you are pregnant or breastfeeding (Gardner and McGuffin 2013; Brinker 2010).", "Do not use if you have inflammatory bowel disease, fever or any undiagnosed gastrointestinal trouble (EMA 2016; Gardner and McGuffin 2013; Brinker 2010).", "Stop use if hypersensitivity/allergy or diarrhea occurs (EMA 2016; Brinker 2010)."]'::jsonb, '["Adolescents 12-17 years, Adults 18 years and older (EMA 2016; Brinker 2010).", "Dry, Powdered, Non-Standardized (Dry extract, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "50 - 300 milligrams dried latex, per day; and providing at least 50 mg of dried latex per single dose (Williamson 2003; Bradley 1992).", "Standardized extracts (Dry extract, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "10 - 30 milligrams hydroxyanthracene derivatives (calculated as barbaloin/aloin), per day; and providing at least 10 mg of hydroxyanthracene derivatives (calculated as barbaloin/aloin) per single dose (EMA 2016; Barnes st al, 2007; Blumenthal et al. 1998)"]'::jsonb, 'imported-ogl-canada'),
  ('alpha-lipoic-source', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=alpha.lipoic.acid2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Source of (an) antioxidant(s)/Provides (an) antioxidant(s) (Borcea et al. 1999, Marangon et al.1999)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of (an) antioxidant(s)/Provides (an) antioxidant(s) that help(s) fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (Borcea et al. 1999, Marangon et al.1999)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to promote healthy glucose metabolism (Morcos et al. 2001, Jacob et al. 1999, Konrad et al. 1999)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes (Jacob et al. 1999, Konrad et al. 1999, Packer et al. 1995).", "Products providing 42 milligrams or more DL-alpha-lipoic acid or 21 milligrams or more R-alpha-lipoic acid, per day", "Stop use and ask a health care practitioner/health care provider/health care professional/doctor/physician if you experience sweating, paleness, chills, headache, dizziness and/or confusion (as these may be symptoms of serious low blood sugar) (Bae et al., 2013; Gullo et al., 2014; Bresciani et al., 2011; Chang et al., 2009).", "No statement required."]'::jsonb, '["Adults 18 years and older", "DL-alpha-Lipoic acid", "Antioxidant", "Not to exceed 600 milligrams of DL-alpha-Lipoic acid, per day (Morcos et al. 2001, Borcea et al. 1999, Marangon et al.1999).", "Glucose metabolism", "600 milligrams of DL-alpha-Lipoic acid, per day (Jacob et al. 1999, Konrad et al. 1999).", "R-alpha-Lipoic acid", "Antioxidant", "Not to exceed 300 milligrams of R-alpha-Lipoic acid", ", per day.", "Glucose metabolism", "300 milligrams of R-alpha-Lipoic-acid", ", per day.", "Note:", "The quantity of R-alpha-lipoic acid is calculated from the quantity of DL-alpha-lipoic acid (i.e. 50%)."]'::jsonb, 'imported-ogl-canada'),
  ('wood-avens', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=avens2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as an antidiarrheal) to help relieve diarrhea (Wichtl 2004; Williamson et al. 1988; BHP 1983; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as a febrifuge) to help reduce fever (Williamson et al. 1988; BHP 1983; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as an astringent) to help relieve sore throats (Wichtl 2004; Williamson et al. 1988; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as a stomachic) to aid digestion (Wichtl 2004; Williamson et al. 1988; Grieve 1971)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "No statement required."]'::jsonb, '["Adults 18 years and older", "1 - 12 grams of dried herb top and/or root, per day (Wichtl 2004; BHP 1983; Grieve 1971).", "Note:", "Solvents allowed for the method of preparation \"Non-Standardized Extracts (Dry extract)\" as part of this monograph are ethanol and/or water only."]'::jsonb, 'imported-ogl-canada'),
  ('bilberry', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=bilberry.myrtille.oral&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine as an astringent to help relieve diarrhea (ESCOP 2003; Blumenthal et al. 2000; Mills and Bone 2000; Grieve 1971; Felter and Lloyd 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants (Upton 2001; Mills and Bone 2000)"}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants that help fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (Upton 2001; Mills and Bone 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help slow the progression of disorders of the eye, such as diabetic and hypertensive retinopathy, and macular degeneration (Mills and Bone 2005; Blumenthal 2003; Upton 2001; Morazzoni and Bombardelli 1996)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help relieve symptoms related to non-complicated chronic venous insufficiency (CVI), such as sensation of swelling, heaviness and tingling of the legs (Barnes 2007; Mills and Bone 2005; ESCOP 2003; Upton 2001)."}]'::jsonb, '["Relief of diarrhea", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Slowing the progression of disorders of the eye and to relieve symptoms related to non-complicated CVI", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms worsen.", "No statement required."]'::jsonb, '["Adults 18 years and older", "Slowing the progression of disorders of the eye; Relieving symptoms related to non-complicated CVI", "160 - 480 milligrams of dried extract standardized to 36% anthocyanins, per day; Not to exceed 160 milligrams per single dose (USP-NF 2023; Blumenthal 2003; ESCOP 2003; Upton 2001).", "Antioxidant", "Not to exceed 75 grams of dried fruit, per day (USP-NF 2023; Barnes 2007; ESCOP 2003; Blumenthal et al. 2000; Grieve 1971).", "Standardized preparations only: not to exceed 36% anthocyanins.", "Relief of diarrhea", "1.8 - 75 grams of dried fruit, per day (USP-NF 2023; Barnes 2007; ESCOP 2003; Blumenthal et al. 2000; Grieve 1971).", "Standardized preparations only: not to exceed 36% anthocyanins"]'::jsonb, 'imported-ogl-canada'),
  ('colostrum-bovine', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=bovine.colostrum.bovin2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Helps maintain/support immune function within the upper respiratory tract (Davison and Diment 2009; Cesarone et al. 2007; Crooks et al. 2006; Patel and Rana 2006; Brinkworth and Buckley 2003; Mero et al. 2002)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps maintain/support the immune system (Davison and Diment 2009; Cesarone et al. 2007; Crooks et al. 2006; Patel and Rana 2006; Brinkworth and Buckley 2003; Mero et al. 2002)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes, a history of cancer, or an immune system disorder (Kim et al. 2009; Rowlands 2009; Salvioli et al. 2009; Tripathi et al. 2006; Albers et al. 2005; Mero et al. 2002; Mero et al. 1997).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Albers et al. 2005).", "Do not use if you have a known allergy/hypersensitivity to cow''s milk (HC 2012).", "No statement required.", "Non Medicinal Ingredients", "Natural Health Products Regulations", "."]'::jsonb, '["Adults 18 years and older", "Method of preparation:", "Powdered", "0.4 - 10 grams of dried colostrum, per day (Kim et al. 2009; Cesarone et al. 2007; Shing et al. 2007; Shing et al. 2006)."]'::jsonb, 'imported-ogl-canada'),
  ('carum-carvi-herb', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=caraway.carvi2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a stomachic) to aid digestion and to help stimulate appetite (Bradley 2006; Wichtl 2004; Hoffmann 2003; Ellingwood 1983; Felter and Lloyd 1983a; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as an antispasmodic) to help relieve digestive spasms and indigestion (Bradley 2006; ESCOP 2003; Hoffmann 2003; Blumenthal 1998; Felter and Lloyd 1983a,b; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a carminative) to help relieve flatulent dyspepsia (Bradley 2006; ESCOP 2003; Hoffmann 2003; Blumenthal 1998; Felter and Lloyd 1983a,b; Grieve 1971)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen (ESCOP 2003).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have acute abdominal pain (ESCOP 2003).", "No statement required.", "Stop use if hypersensitivity/allergy occurs (Brinker 2010; ESCOP 2003)."]'::jsonb, '["As specified below.", "1,", "2", "Caraway dried seed (g/day)", "Minimum", "Maximum", "Infants", "6-12 months", "0.06 g", "1 g", "Children", "1-3 years", "0.3 g", "2 g", "4-9 years", "0.3 g", "4 g", "10-11 years", "0.3 g", "15 g", "Adolescents", "12-17 years", "0.3 g", "15 g", "Adults"]'::jsonb, 'imported-ogl-canada'),
  ('frangula-purshiana', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=cascara.sagrada2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "[(Traditionally) used in Herbal Medicine as a] stimulant laxative (Williamson 2003; Blumenthal et al. 2000; Moerman 1998; Felter and Lloyd 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine for the) short-term relief of occasional constipation (EMA 2020; Mills and Bone 2005; WHO 2002)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine to) promote(s) bowel movement (by direct action on the large intestine) (EMA 2020; Sweetman 2007; Blumenthal et al. 2000)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have a kidney disorder or a lazy bowel (EMA 2020; Brinker 2010; WHO 2002).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2020; Brinker 2010; WHO 2002; Blumenthal et al. 2000).", "Do not use if you are pregnant or breastfeeding (EMA 2020; Brinker 2010; Blumenthal et al. 2000).", "Do not use if you have inflammatory bowel disease, fever or any undiagnosed gastrointestinal trouble (EMA 2020; Brinker 2010; WHO 2002).", "Stop use if hypersensitivity/allergy or diarrhea occurs (EMA 2020; Brinker 2010)."]'::jsonb, '["Adolescents 12 to 17 years and Adults 18 years and older (EMA 2020; Mills and Bone 2005; ESCOP 2003; Berardi et al. 2002)", "Dry, Powdered, Non-Standardized Extracts (Dry extract, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "0.25 - 3 grams of dried aged bark, per day; and providing at least 0.25 g of dried aged bark per single dose (Mills and Bone 2005, ESCOP 2003; Williamson 2003; WHO 2002; Blumenthal et al. 2000; Bradley 1992).", "Standardized Extracts (Dry extract, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "10 - 30 milligrams of hydroxyanthracene derivatives (calculated as cascaroside A), per day; and providing at least 10 mg of hydroxyanthracene derivatives (calculated as cascaroside A) per single dose (EMA 2020; Mills and Bone 2005; ESCOP 2003; Blumenthal et al. 2000)."]'::jsonb, 'imported-ogl-canada'),
  ('chamomile', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=cham.germ.oral.orale2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help relieve inflammatory conditions of the gastrointestinal tract (Blumenthal et al. 2000; Bradley 1992)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve mild digestive upset (such as dyspepsia, flatulence, bloating and belching) (Mills and Bone 2005; ESCOP 2003; Bradley 1992; Felter 1922; Ellingwood 1919; Felter and Lloyd 1898)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve restlessness and/or nervousness (which helps to promote sleep) (nervine/calmative) (Blumenthal et al. 2000; WHO 1999; Bradley 1992; Felter 1922; Ellingwood 1919; Felter and Lloyd 1898)."}]'::jsonb, '["When using this product exercise caution if you drive or use machinery as you may experience drowsiness.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "No statement required.", "Stop use if hypersensitivity/allergy occurs (ESCOP 2003; Bradley 1992)."]'::jsonb, '["As specified below.", "Dry, Powdered, Non-Standardized Extracts (Dry extract*, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "1", ",", "2", "Chamomile dried flower (g/day)", "Minimum", "Maximum", "Children", "2-4 years", "0.3 g", "4.0 g", "5-9 years", "0.4 g", "6.0 g", "10-11 years", "0.8 g", "12.0 g", "Adolescents", "12-14 years", "0.8 g", "12.0 g", "15-17 years", "1.5 g", "24.0 g"]'::jsonb, 'imported-ogl-canada'),
  ('vitex', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=chaste.tree.vitex&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help relieve premenstrual symptoms (WHO 2009; Bradley 2006; Wichtl 2004; ESCOP 2003; Hoffmann 2003; Blumenthal et al. 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine (as a hormone normaliser) to help stabilise menstrual cycle irregularities (WHO 2009; Bradley 2006; Wichtl 2004; ESCOP 2003; Hoffmann 2003; Blumenthal et al. 2000; Mills and Bone 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help relieve symptoms associated with menopause, such as hot flushes (WHO 2009; Hoffmann 2003)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking hormone-containing medications such as progesterone preparations, oral contraceptives or hormone replacement therapy (Brinker 2010; WHO 2009; Bradley 2006).", "Do not use if you are pregnant, breastfeeding or attempting to conceive unless you have consulted with a health care practitioner/health care provider/health care professional/doctor/physician (EMA 2018; Najib et al. 2022; Brinker 2010; WHO 2009; Dugoua et al. 2008; ESCOP 2003; Blumenthal 2000; Mills and Bone 2000).", "No statement required."]'::jsonb, '["Adults 18 years or older", "Dry, Powder, Non-Standardized Extracts (Dry extract", ", Tincture, Fluid extract, Decoction, Infusion)", "30 - 2000 milligrams of dried fruit, per day (WHO 2009; Bradley 2006; ESCOP 2003; Hoffmann 2003; Blumenthal et al. 2000; Mills and Bone 2000).", "Notes:", "Solvents allowed for the method of preparation \"Non-standardized extracts (Dry extract)\" as part of this monograph are ethanol and/or water only.", "When ‘decoction’ or ‘infusion’ is listed as an acceptable method of preparation, ‘decoction concentrate’ or ‘infusion concentrate’ is also allowed."]'::jsonb, 'imported-ogl-canada'),
  ('coq10-antioxidant', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=coenzyme.q10&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Helps to maintain and/or support cardiovascular health (Rosenfeldt et al. 2007; Baggio et al. 1994; Langsjoen et al. 1988)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to reduce the frequency of migraine headaches and associated nausea and vomiting when taken as a prophylactic/preventative (Hershey et al. 2007; Sandor et al. 2005; Rozen et al. 2002)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of (an) antioxidant(s)/Provides (an) antioxidant(s) (Kalpravidh et al. 2005; Rosenfeldt et al. 2005; Crane 2001; Chello et al. 1994)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of (an) antioxidant(s)/Provides (an) antioxidant(s) that help(s) fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (Kalpravidh et al. 2005; Rosenfeldt et al. 2005; Crane 2001; Chello et al. 1994)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood pressure medication (Rosenfeldt et al. 2007; Singh et al. 1999).", "Products providing more than 100 mg of Coenzyme Q10 per day", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Engelsen et al. 2003; Landbo and Almdal 1998; Spigset 1994).", "Migraine prophylaxis/prevention", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if migraine frequency increases and associated nausea and vomiting persist or worsen.", "No statement required."]'::jsonb, '["Adults 18 years and older", "Antioxidant", "Not to exceed 300 milligrams of Coenzyme Q10, per day (Bonakdar and Guarneri 2005; Kalpravidh et al. 2005; Rosenfeldt et al. 2005; Chello et al. 1994; Langsjoen 1994; Langsjoen et al. 1988; Tanaka et al. 1982)", "Cardiovascular health", "30 - 300 milligrams of Coenzyme Q10, per day (Bonakdar and Guarneri 2005; Kalpravidh et al. 2005; Rosenfeldt et al. 2005; Chello et al. 1994; Langsjoen 1994; Langsjoen et al. 1988; Tanaka et al. 1982)", "Migraine prophylaxis", "150 - 300 milligrams of Coenzyme Q10, per day (Sandor et al. 2005; Rozen et al. 2002)"]'::jsonb, 'imported-ogl-canada'),
  ('hawthorn', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=crataegus.monogyna&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Fruit"}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to help maintain and/or support cardiovascular health in adults (ESCOP 2009; Bradley 2006; Wichtl 2004; ESCOP 2003; WHO 2002; Mills and Bone 2000; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "Fruit; Flower and leaf"}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help maintain and/or support cardiovascular health in adults (Bradley 2006; Wichtl 2004; Degenring et al. 2003; ESCOP 2003; WHO 2002; Mills and Bone 2000)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking cardiac glycosides (e.g., digoxin) or blood pressure or heart medications (Brinker 2010; Bradley 2006).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have chest pain, irregular heartbeat, or shortness of breath.", "No statement required."]'::jsonb, '["Adults 18 years and older", "Fruit", "Traditional and Non-traditional Herbal Medicine claims", "Powdered, Non-Standardized Ethanolic Extracts (Dry extract, Tincture, Fluid extract)", "0.6 - 3.5 grams of dried fruit, per day (ESCOP 2009; Bradley 2006; Grieve 1971).", "Dry", ", Non-Standardized Aqueous Extracts (Dry extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "1.5 - 6 grams of dried fruit, per day (EMA 2016; Bradley 2006; Mills and Bone 2000).", "Note:", "Dried fruit should be prepared as an infusion or decoction by consumers prior to use (see direction for use).", "Non-traditional Herbal Medicine claim", "Standardized Ethanolic Extracts (Liquid extract)", "Liquid extract equivalent to 700 milligrams of fresh fruit per day, providing a minimum of 6.4 mg Oligomeric proanthocyanidins (OPC), per day (Degenring 2003).", "Flower and leaf", "Non-traditional Herbal Medicine claim", "Dry", ", Powdered, Non-Standardized Extracts (Dry extract, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "1.5 - 5 grams of dried flower and leaf, per day (Bradley 2006; ESCOP 2003).", "Note:", "Dried flower and leaf should be prepared as an infusion or decoction by consumers prior to use (see direction for use).", "Standardized Ethanolic Extracts (Dry extract)", "160 - 900 milligrams of extract, per day, standardized to 18.75% of Oligomeric procyanidins, as epi-catechin, and/or to 2.2% of flavonoids, as hyperoside (WHO 2002; Blumenthal et al. 2000)."]'::jsonb, 'imported-ogl-canada'),
  ('licorice-dgl', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=deg.lic.reg.oral.orale2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine (as a demulcent) to) help(s) relieve minor inflammations of the gastrointestinal tract (Pizzorno and Murray 2006; Blumenthal et al. 2000; Bradley 1992)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine (as a demulcent) to) help(s) relieve abdominal pain and burning sensation in the stomach (Pizzorno and Murray 2006; Blumenthal et al. 2000; Bradley 1992)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "No statement required."]'::jsonb, '["As listed below.", "Method of preparation: Prepared and dry", "1,2", "Deglycyrrhizinated licorice extract (mg)", "Minimum/single dose", "Maximum/single dose", "Frequency/day", "Children", "3-4 years", "63 mg", "253 mg", "3 times", "5-9 years", "95 mg", "380 mg", "3 times", "10-11 years", "190 mg", "760 mg", "3 times", "Adolescents", "12-14 years", "190 mg", "760 mg", "3 times"]'::jsonb, 'imported-ogl-canada'),
  ('echinacea', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=echinacea.purpurea2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to help relieve cold symptoms (Moerman 1998; Grieve 1971; Remington and Wood 1918)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to help relieve symptoms of upper respiratory tract infections (Moerman 1998; Grieve 1971; Remington and Wood 1918)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help fight off infections, especially of the upper respiratory tract (Hoffmann 2003; Mills and Bone 2000; Grieve 1971; Remington and Wood 1918)."}, {"section": "Use(s) or Purpose(s)", "text": "Supportive therapy in the treatment of upper respiratory tract infections (e.g. common colds) (Goel et al. 2004; Schulten et al. 2001; Brinkeborn et al. 1999; Hoheisel et al. 1997; Bräunig et al. 1992)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to relieve the symptoms and shorten the duration of upper respiratory tract infections (Goel et al. 2004; Schulten et al. 2001; Brinkeborn et al. 1999; Hoheisel et al. 1997; Bräunig et al. 1992)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have a progressive systemic disease such as tuberculosis, collagenosis, multiple sclerosis, or an immune system disorder (EMA 2015; Gardner and McGuffin 2013; Brinker 2010).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Brinker 2010; Mills and Bone 2005).", "No statement required.", "Preparations containing herb top", "Stop use if hypersensitivity/allergy occurs (MHRA 2018; EMA 2015; Kligler 2003; WHO 1999)."]'::jsonb, '["As specified below.", "HERB TOP", "1", ",", "2", "Dried herb top (g/day)", "Minimum", "Maximum", "Children", "2-4 years", "0.4 g", "1.0 g", "5-9 years", "0.6 g", "1.5 g", "10-11 years", "1.3 g", "3.0 g", "Adolescents", "12-14 years", "1.3 g", "3.0 g", "15-17 years", "2.5 g", "6.0 g"]'::jsonb, 'imported-ogl-canada'),
  ('ephedra-sinica', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ephedra2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as a decongestant/to relieve nasal congestion (due to hay fever/allergic rhinitis/allergies/sinusitis/the common cold/flu) (Mills and Bone 2005; Mehendale et al. 2004; Hoffman 2003; Blumenthal et al. 2000; BHP 1983)."}]'::jsonb, '["Keep out of reach of children. In case of overdose, call a poison control centre or get medical help right away.", "Stop use and ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms worsen or last (for) more than 7 days.", "Stop use and ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms are accompanied by a high fever that lasts longer than 3 days, the production of thick yellow/green phlegm, rash or a persistent headache.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding (Brinker 2010; Hackman et al. 2006; Kuczkowski 2006; Mills and Bone 2005; Coffey et al. 2004; Greenway et al. 2004; Haller et al. 2004; Hoffman 2003; Boozer et al. 2002; Boozer et al. 2001; Kalman et al. 2000).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking any other cough and cold or weight control medications or prescription drugs, or products which contain caffeine, ephedrine or pseudoephedrine (Brinker 2010; Hackman et al. 2006; Mills and Bone 2005; Greenway et al. 2004; Naik and Freudenberger 2004; Boozer et al. 2002; Boozer et al. 2001; Haller and Benowitz 2000; Kalman et al. 2000).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have asthma, diabetes, glaucoma, heart disease, high blood pressure, kidney disease, difficulty urinating, thyroid disease, seizure disorders, or any other serious medical condition (US FDA 2022; Brinker 2010; Hackman et al. 2006; Mills and Bone 2005; Bensky et al. 2004; Coffey et al. 2004; Greenway et al. 2004; Haller et al. 2004; Hioki et al. 2004; Mehendale et al. 2004; Hoffman 2003; Williamson 2003; Boozer et al. 2002; Boozer et al. 2001; Blumenthal et al. 2000; Kalman et al. 2000; BHP 1983).", "Do not use with a monoamine oxidase inhibitor (MAOI) or for 2 weeks after stopping the MAOI drug (Brinker 2010; Greenway et al. 2004; Hoffman 2003; Blumenthal et al. 2000; Kalman et al. 2000; Dingemanse et al. 1996; Dawson et al. 1995; Elis et al. 1967).", "Stop use and ask a health care practitioner/health care provider/health care professional/doctor/physician if you experience severe headache, confusion, visual changes/change in vision, nervousness, dizziness, sleeplessness, nausea, rapid heartbeat, difficulty or pain when urinating, or allergic reactions (Khang et al. 2024; Ryu et al. 2017; Brinker 2010; Bensky et al. 2004; Mehendale et al. 2004; Shekelle et al. 2003; Boozer et al. 2001; Astrup et al. 1992)."]'::jsonb, '["Adults 18 years and older", "Extract providing 8 - 32 milligrams of l-Ephedrine, per day; Not to exceed 8 milligrams of l-Ephedrine per single dose; and Quantity crude equivalent 400 - 1,600 milligrams of dried branchlet and/or branch, and/or stem, per day (HC 2008; MHRA 2005; US FDA 2004; Pickup et al. 1976)."]'::jsonb, 'imported-ogl-canada'),
  ('fennel', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=fennel.fenouil.sweet.doux2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve digestive upset including bloating and flatulence (EMA 2024)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve the pain associated with menstruation (EMA 2024)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine as an expectorant to help relieve coughs associated with colds (EMA 2024)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding (EMA 2024).", "No statement required.", "Stop use if hypersensitivity/allergy occurs (EMA 2024)."]'::jsonb, '["Children 4-11 years, Adolescents 12-17 years, Adults 18 years and older (EMA 2024).", "Children 4-11 years", "Dry", "1", ", Non-Standardized Aqueous Extracts (Dry extract, Infusion, Infusion concentrate)", "3 - 5 grams of dried fruit/seed, per day; Not to exceed 1.6 grams per single dose (EMA 2024).", "1", "Note:", "Dried fruit/seed should be prepared as an infusion (see direction for use).", "Adolescents 12-17 years; Adults 18 year and older", "Dry, Powdered, Non-Standardized Ethanolic Extracts (Dry extract, Tincture, Fluid extract)", "1.2 grams of dried fruit/seed, per day; Not to exceed 0.4 grams per single dose (EMA 2007).", "Dry", "1", ", Non-Standardized Aqueous Extracts (Dry extract, Infusion, Infusion concentrate)", "4.5 - 7.5 grams of dried fruit/seed, per day; Not to exceed 2.5 grams per single dose (EMA 2024).", "1", "Note:", "Dried fruit/seed should be prepared as an infusion (see direction for use)."]'::jsonb, 'imported-ogl-canada'),
  ('fenugreek', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=fenugreek.oral2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants (HC 2026)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants that help fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (HC 2026)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help stimulate the appetite (Bradley 2006; Mills and Bone 2005; Blumenthal et al. 2000; Khory and Katrak 1999)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a digestive tonic) to aid digestion (Williamson et al. 1988; Mills 1985; Felter and Lloyd 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve dyspepsia and gastritis (Bradley 2006; Blumenthal et al. 2000; Mills 1985; Grieve 1971; Wren 1907)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as a mild laxative (Bradley 2006; Williamson 2003; Mills 1993)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as an expectorant) to help relieve excess mucous of the upper respiratory passages (anticatarrhal) (Wichtl 2004; Williamson 2003; Felter and Lloyd 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine as a nutritive tonic (Bradley 2006; Mills and Bone 2005; Blumenthal et al. 2000; Khory and Katrak 1999; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a galactogogue/lactogogue) to help promote milk production/secretion (Bradley 2006; Mills and Bone 2005; Williamson 2002)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine as supportive therapy for the promotion of healthy glucose levels (Bradley 2006; Mills and Bone 2005; Williamson 2002; API 2001; Al-Habori and Raman 1998; Sharma and Raghuram 1990)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help reduce elevated blood lipid levels (hyperlipidemia) (Mills and Bone 2005; Hoffman 2003; Al-Habori and Raman 1998; Sharma and Raghuram 1990)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant (Gardner and McGuffin 2013; Brinker 2010; Mills et al. 2006; Hoffman 2003; Blumenthal et al. 2000).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes (Brinker 2010; Mills and Bone 2005).", "No statement is required."]'::jsonb, '["Adults 18 years and older", "Antioxidants", "Dry, Powdered, Non-Standardized Extracts (Dry extract, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "Up to 30 grams of dried seeds, per day (Bradley 2006; Mills and Bone 2005; API 2001; Blumenthal et al. 2000; Mills 1985; Felter and Lloyd 1983; Grieve 1971; Wren 1907).", "Other uses", "Dry, Powdered, Non-Standardized Extracts (Dry extract, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "2 - 30 grams of dried seeds, per day (Bradley 2006; Mills and Bone 2005; API 2001; Blumenthal et al. 2000; Mills 1985; Felter and Lloyd 1983; Grieve 1971; Wren 1907)."]'::jsonb, 'imported-ogl-canada'),
  ('scrophularia', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=figwort.scrofulaire&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine as a diuretic (Hoffmann 2003; Felter and Lloyd 1983; Wren 1907)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine as an analgesic (anodyne) (Bartram 1998; Felter and Lloyd 1983; Wren 1907)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to relieve symptoms of chronic cutaneous diseases (Hoffmann 2003; Wren 1907)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to relieve symptoms of eczema (Hoffmann 2003; BHP 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to relieve symptoms of psoriasis (Hoffmann 2003; BHP 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to relieve symptoms of pruritus (Hoffmann 2003; BHP 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine as a mild laxative (Hoffmann 2003; Williamson et al. 1988; Mills 1985)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have heart disease (Brinker 2010; Hoffmann 2003).", "No statement required.", "All products except those making only a diuretic claim*", "When using this product diuretic effect may occur.", ": This statement can be removed from the label if a diuretic claim is included."]'::jsonb, '["Adults 18 years and older", ": Dry, Powdered, Non-Standardized Extracts (Dry extract*, Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "0.2 - 8 grams dried herb top, per day (Hoffmann 2003; Bartram 1998; BHP 1983; Felter and Lloyd 1983).", ": Solvents allowed for the method of preparation “Non-Standardized Extracts (Dry extract)” as part of this monograph are ethanol and/or water."]'::jsonb, 'imported-ogl-canada'),
  ('yellow-gentian-root', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=gentian2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve digestive disturbances (such as dyspepsia) (Mills and Bone 2005; ESCOP 2003; Hoffmann 2003; Blumenthal et al. 2000; Bradley 1992;Williamson et al. 1988; Felter and Lloyd 1983; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a digestive tonic and bitter) to help stimulate appetite and (as a stomachic) to aid digestion (Mills and Bone 2005; Wichtl 2004; Hoffmann 2003; Blumenthal et al. 2000; Bradley 1992; Williamson et al.1988; Felter and Lloyd 1983; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as an antiemetic) to help prevent nausea (Bradley 1992; Williamson et al. 1988)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine (as a cholagogue) to help increase bile flow (Wichtl 2004; Hoffmann 2003; Blumenthal et al. 2000)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are breastfeeding.", "Do not use if you are pregnant (Hoffmann 2003; Morimoto et al.1983).", "Do not use if you have stomach or duodenal acute inflammation or ulcer (Brinker 2010; ESCOP 2003; Bradley 1992).", "When using this product you may experience headaches (ESCOP 2003; Hoffmann 2003; Blumenthal et al. 2000)."]'::jsonb, '["Adults 18 years and older", "0.1 - 6 grams of dried root, per day (Mills and Bone 2005; ESCOP 2003; Hoffmann 2003; Blumenthal et al.2000; Bradley 1992)", "Note:", "Solvents allowed for the method of preparation “Non-Standardized Extracts (Dry extract)” as part of this monograph are ethanol and/or water only."]'::jsonb, 'imported-ogl-canada'),
  ('american-ginseng', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ginseng.american2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Used in Traditional Chinese Medicine (TCM) for deficiency of qi and yin, internal heat, cough, fire in the deficiency syndrome, dysphoria and tiredness, dry and thirsty mouth and throat (PPRC 2020)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as supportive therapy for the promotion of healthy (blood) glucose/sugar levels (Dascalu et al. 2007; Vuksan et al. 2000a,b,c)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve restlessness and/or nervousness (nervine/calmative) (Bartram 1998; Ellingwood 1998)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve nervous dyspepsia/to help digestion in cases of nervousness and/or stress (Bartram 1998; Felter and Lloyd 1983; Wren 1956)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as an adaptogen to help maintain a healthy immune system (Upton 2012; Godfrey et al. 2010; Bartram 1998)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as an adaptogen to help increase energy and resistance to stress over time (e.g. in case of mental and physical fatigue related to stress) (Upton 2012; Winston and Maimes 2007)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or digoxin (Brinker 2010; Dasgupta et al. 2007; Elmer et al. 2007; Yuan et al. 2004).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes (Brinker 2010; Dascalu et al. 2007; Vuksan et al. 2000a,b,c).", "All products except Glucose levels and Adaptogen - immune system", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "No statement required."]'::jsonb, '["Adults 18 years and older", "Glucose levels; Restlessness/Nervousness; Nervous dyspepsia/Digestion", "0.5 - 12 grams dried root, per day (Bartram 1998; Felter and Lloyd 1983; Wren 1956).", "Note:", "Solvents allowed for the method of preparation “Non-Standardized extracts (Dry extract)” as part of this monograph are ethanol and/or water only.", "Adaptogen - energy and resistance to stress; Adaptogen - immune system", "1 - 3 grams dried root, per day (Upton 2012; Winston and Maimes 2007).", "Adaptogen - energy and resistance to stress", "6 - 9 grams dried root, per day; Not to exceed 3 grams per single dose (Winston and Maimes 2007).", "TCM", "2.4 - 9 grams dried root, per day (PPRC 2020; Bensky et al. 2004)."]'::jsonb, 'imported-ogl-canada'),
  ('ginseng', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ginseng.panax2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine as) supportive therapy for the promotion of healthy glucose levels (Vuksan et al. 2008; Sievenpiper et al. 2006; Williamson 2003; Tetsutani et al. 2000; WHO 1999; Sotaniemi et al. 1995)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine to) help(s) support cognitive function and/or reduce mental fatigue (in cases of mental stress) (Reay et al. 2006; Reay et al. 2005; Sünram-Lea et al. 2005; Kennedy et al. 2004; ESCOP 2003; Kennedy et al. 2002; Scholey and Kennedy 2002; Kennedy et al. 2001; Sorensen and Sonne 1996; Bradley 1992; D’Angelo et al. 1986; BHP 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps support cognition (Reay et al. 2006; Reay et al. 2005; Sünram-Lea et al. 2005; Kennedy et al. 2004; ESCOP 2003; Kennedy et al. 2002; Scholey and Kennedy 2002; Kennedy et al. 2001; Sorensen and Sonne 1996; Bradley 1992; D’Angelo et al. 1986; BHP 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine to) help(s) enhance physical capacity/performance (in cases of physical stress) (Kim et al. 2005; ESCOP 2003; Gross et al. 2002; WHO 1999; Gross et al. 1995; Sotaniemi et al. 1995; Schepdael 1993)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as an adaptogen to help increase energy and resistance to stress over time (e.g. in case of mental and physical fatigue related to stress) (Winston and Maimes 2007; Bone 2003; Hoffman 2003; Blumenthal et al. 2000; WHO 1999; Bradley 1992)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Traditional Chinese Medicine (TCM) to reinforce qi, benefit the spleen and lung, relieve symptoms of thirst due to impairment of body fluids and internal heat (PPRC 2020; Bensky et al. 2004; Chen and Chen 2004)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes (Brinker 2010; Vuksan et al. 2008; Seely et al. 2008; Sievenpiper et al. 2006; ESCOP 2003; Tetsutani et al. 2000; Sotaniemi et al. 1995; Chin 1991).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, blood thinners or digoxin (Brinker 2010; Lee et al. 2008a; Dasgupta and Reyes 2005; Janetzki and Morreale 1997; Gonzalez-Seijo et al. 1995; Shader and Greenblatt 1988; Jones and Runikis 1987; Shader and Greenblatt 1985).", "Traditional Chinese Medicine", "Do not use in cases of yin deficiency with heat signs, heat excess, or in the absence of significant qi deficiency (Bensky et al. 2004).", "Stop use and ask a health care practitioner/health care provider/health care professional/doctor/physician if you experience insomnia, anxiety or headaches (Lee et al. 2008b; Vuksan et al 2008; de Andrade et al.2007; Sievenpiper et al. 2006; Coon and Ernst 2002; Ellis and Reddy 2002; Scaglione et al. 2001; Siegel 1979)."]'::jsonb, '["Adults 18 years and older", "Glucose levels; Cognitive function/cognition; Mental stress; Physical stress; Adaptogen", "Standardized extracts (Dry extract)", "200 - 600 milligrams of extract, per day; standardized to 4 - 7% total ginsenosides; Not to exceed 9 grams of dried root/rootlet, per day (Vuksan et al. 2008; Reay et al. 2006; Sievenpiper et al. 2006; Reay et al. 2005; Sünram-Lea et al. 2005; Kennedy et al. 2004; ESCOP 2003; Kennedy et al. 2002; Scholey and Kennedy 2002; Engels et al. 2001; Kennedy et al. 2001; Scaglione et al. 2001; Blumenthal et al. 2000; Tetsutani et al. 2000; Engels et al. 1996; Scaglione et al. 1996; Gross et al. 1995; Scaglione et al. 1994; Scaglione et al. 1990; Petkov and Mosharrof 1987; D’Angelo et al. 1986; Soldati and Sticher 1980).", "Dry, Powdered, Non-Standardized Extracts (Dry extract, Tincture, Fluid extract, Decoction, Infusion)", "0.5 - 9 grams dried root/rootlets, per day (Vuksan et al. 2008; Reay et al. 2006; Sievenpiper et al. 2006; Reay et al. 2005; Sunram-Lea et al. 2005; Kennedy et al. 2004; ESCOP 2003; Kennedy et al. 2002; Scholey and Kennedy 2002; Engels et al. 2001; Kennedy et al. 2001; Scaglione et al. 2001; Blumenthal et al. 2000; Engels et al. 1996; Scaglione et al. 1996; Gross et al. 1995; Scaglione et al. 1994; Scaglione et al. 1990; Petkov and Mosharrof 1987; D''Angelo et al. 1986; Soldati and Sticher 1980).", "Traditional Chinese Medicine", "Decoction, Decoction concentrate", "3 - 10 grams dried root, per day (PPRC 2020; Bensky et al. 2004, Chen and Chen 2004).", "Powdered (unextracted)", "0.5 - 4 grams dried root, per day (PPRC 2020, Bensky et al. 2004, Chen and Chen 2004)."]'::jsonb, 'imported-ogl-canada'),
  ('artichoke', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=globe.artichoke.artichaut2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help relieve digestive disturbances/dyspepsia (EMA 2018; Bradley 2006; ESCOP 2003; Blumenthal et al. 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine (as a choleretic) to help increase bile flow (Bradley 2006; Mills and Bone 2005; ESCOP 2003; Hoffmann 2003; Blumenthal et al. 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants (Olas 2024; Skarpanska-Stejnborn et al. 2008)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants that help fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (Olas 2024; Skarpanska-Stejnborn et al. 2008)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant (Barnes et al. 2007; Mills and Bone 2005; ESCOP 2003).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have gallstones (Brinker 2010; Mills and Bone 2005; ESCOP 2003; Blumenthal et al. 2000).", "Digestive disturbance/dyspepsia/Help increase bile flow", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Do not use if you have a bile duct obstruction (EMA 2018; Brinker 2010; Bradley 2006; ESCOP 2003; Blumenthal et al. 2000).", "Stop use if hypersensitivity/allergy occurs (EMA 2018; Brinker 2010; Bradley 2006; ESCOP 2003; Blumenthal et al. 2000)."]'::jsonb, '["Adults 18 years and older", "Dried leaf", "Antioxidant", "Not to exceed 10 grams of dried leaf, per day (EMA 2018; Mills and Bone 2005; ESCOP 2003; Blumenthal et al. 2000).", "Digestive disturbance/dyspepsia/Help increase bile flow", "0.6 - 10 grams of dried leaf, per day (EMA 2018; Mills and Bone 2005; ESCOP 2003; Blumenthal et al. 2000).", "Method of preparation: Soft extract concentrate*", "Antioxidant", "Not to exceed 2.1 grams of soft extract concentrate, per day; equivalent to a maximum of 7.35 grams of dried leaf, per day; and do not exceed 0.7 grams of soft extract concentrate, per single dose (EMA 2018).", "Digestive disturbance/dyspepsia/Help increase bile flow", "0.7 grams of soft extract concentrate, 3 times per day; equivalent to 5.25 - 7.35 grams of dried leaf, per day (EMA 2018).", "Note:", "solvent: ethanol 20% (V/V) in water (EMA 2018).", "Antioxidant", "Not to exceed 10 grams of dried leaf, per day (EMA 2018; Bradley 2006; Mills and Bone 2005; ESCOP 2003).", "Digestive disturbance/dyspepsia/Help increase bile flow", "1.5 - 10 grams of dried leaf, per day (EMA 2018; Bradley 2006; Mills and Bone 2005; ESCOP 2003).", "Note:", "Dried leaves should be prepared as an infusion or decoction by consumers prior to use (see direction for use).", "Fresh leaf", "Method of preparation: Dry extract*", "Antioxidant", "Not to exceed 2.7 grams of dry extract, per day; equivalent to a maximum of 94.5 grams of fresh leaf, per day; and not to exceed 900 milligrams of dry extract, per single dose (EMA 2018).", "Digestive disturbance/dyspepsia/Help increase bile flow", "200 - 900 milligrams of dry extract, 3 times per day; equivalent to 9 - 94.5 grams of fresh leaf, per day (EMA 2018)."]'::jsonb, 'imported-ogl-canada'),
  ('amorphophallus', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=glucomannan&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Helps to lower cholesterol levels (by reducing cholesterol absorption from the gastrointestinal tract) (EFSA 2009; Sood et al. 2008; Martino et al. 2005; Chen et al. 2003; Arvill and Bodin 1995; Walsh et al. 1984)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine as a) bulk-forming laxative (Chua et al. 2010; Chen et al. 2008; Chen et al. 2006; González Canga et al. 2004; Loening-Baucke et al. 2004)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine to) promote(s) bowel movements (by increasing bulk volume and water content) (Chua et al. 2010; Chen et al. 2008; Chen et al. 2006; González Canga et al. 2004; Loening-Baucke et al. 2004)."}, {"section": "Use(s) or Purpose(s)", "text": "(Used in Herbal Medicine to) provide(s) gentle relief of constipation and/or irregularity (Chua et al. 2010; Chen et al. 2008; Chen et al. 2006; González Canga et al. 2004; Loening-Baucke et al. 2004)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician immediately if you experience chest pain, vomiting, or difficulty swallowing or breathing after taking this product (FDA 2023).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes or a lazy bowel (UpToDate 2023; EMA 2013; Chen et al. 2003; Vuksan et al. 2001).", "Laxative; Promotion of bowel movement; Constipation relief", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms worsen or if laxative effect does not occur within 7 days (Pray 2006; Repchinsky 2002).", "Do not use if you have difficulty swallowing (FDA 2023; Sweetman 2007; Vanderbeek et al. 2007; Henry et al. 1986).", "Do not use if you have fever or any undiagnosed gastrointestinal trouble (EMA 2013; Pray 2006; Berardi et al. 2002).", "Stop use if hypersensitivity/allergy occurs (EMA 2013).", "When using this product you may experience temporary gas and bloating (Sood et al. 2008)."]'::jsonb, '["Adults 18 years and older", "Lowering of cholesterol", "1 - 1.5 grams of glucomannan, 3 times per day (EFSA 2009; Martino et al. 2005; Chen et al. 2003; Arvill and Bodin 1995; Walsh et al. 1984)", "Laxative; Promotion of bowel movement; Constipation relief", "0.5 - 5 grams of glucomannan, 3 times per day (Chen et al. 2008; Chen et al. 2006; González Canga et al. 2004; Loening-Baucke et al. 2004)"]'::jsonb, 'imported-ogl-canada'),
  ('coffee-green-extract', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=greencoffeebean.ext.fevescafevert2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Could (be a) complement (to) a healthy lifestyle that incorporates a calorie-reduced diet and regular physical activity for individuals involved in a weight management program (Thom 2007; Dellalibera et al. 2006)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps maintain healthy blood pressure levels (Mubarak et al. 2012; Watanabe et al. 2006; Kozuma et al. 2005)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps support cardiovascular health (Mubarak et al. 2012; Watanabe et al. 2006; Kozuma et al. 2005)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants (Farah et al. 2008; Castellucio et al. 1995)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants that help fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (Farah et al. 2008; Castellucio et al. 1995)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are breastfeeding.", "Do not use if you are pregnant.", "No statement required."]'::jsonb, '["Adults 18 years and older", "Antioxidant", "Not to exceed 1000 milligrams of extract per day, standardized to 45-50% chlorogenic acids and up to 4% of caffeine (Thom 2007).", "Weight Management", "400 –; 1000 milligrams of extract per day, standardized to 45-50% chlorogenic acids and up to 4% caffeine (Thom 2007; Dellalibera et al. 2006).", "Blood pressure; Cardiovascular health", "115 – 1000 milligrams of extract per day, standardized to 45-50% chlorogenic acids and up to 4% caffeine (Thom 2007; Watanabe et al. 2006; Kozuma et al. 2005).", "Blood pressure; Cardiovascular health", "Green coffee bean extract (maximum 4% caffeine) cannot be combined with caffeine or other medicinal or non-medicinal ingredients containing caffeine."]'::jsonb, 'imported-ogl-canada'),
  ('glechoma-hederacea', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ground.ivy.oral2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as a stomachic) to aid digestion (Barnes et al. 2007; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as an expectorant) to help relieve coughs, mucous production (anticatarrhal) and bronchial afflictions (Barnes et al. 2007; Bradley 1992; Williamson et al. 1988)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine (as an astringent) to help relieve diarrhea (Barnes et al. 2007; Bartram 1998; Bradley 1992; Williamson et al. 1988; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine as a diuretic (Barnes et al. 2007; Williamson et al. 1988; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "Traditionally used in Herbal Medicine to help relieve hemorrhoids (Barnes et al. 2007; Williamson et al. 1988)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding (Barnes et al. 2007).", "No statement required.", "All products except those making a diuretic claim", "1", "When using this product diuretic effect may occur.", "Note:", "This statement is not required at a subtherapeutic quantity below 10% of the minimum therapeutic quantity (i.e., < 200 mg of dried herb top per day) as this is based on the therapeutic or residual therapeutic effect of the medicinal ingredient."]'::jsonb, '["Adults 18 years and older", "2 - 12 grams of dried herb top, per day (Bradley 1992; Williamson et al. 1988; Grieve 1971).", "Note:", "Solvents allowed for the method of preparation “Non-Standardized Extracts (Dry extract)” as part of this monograph are ethanol and/or water only."]'::jsonb, 'imported-ogl-canada'),
  ('armoracia-rusticana-herb', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=horseradish.raifort2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to aid digestion (Barnes et al. 2007; Blumenthal et al. 2000; Moerman 1998; Meyer 1993; Felter and Lloyd 1983; Wren 1907)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine as a diuretic (Barnes et al. 2007; Blumenthal et al. 2000; Moerman 1998; Mills 1985; Felter and Lloyd 1983; Grieve 1971; Wren 1907)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are breastfeeding (Barnes et al. 2007; Blumenthal et al. 2000).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have hypothyroidism, excess stomach acid or acid reflux (Brinker 2010; Barnes et al. 2007; Mills 1985).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking thyroid medications or antacids (Brinker 2010; Barnes et al. 2007B; Mills 1985).", "Do not use if you are pregnant (Brinker 2010).", "Do not use if you have a kidney or stomach disorder, or ulcers (Gardner and McGuffin 2013; Brinker 2010; Blumenthal et al. 2000).", "All products except those making", "only", "a diuretic claim*", "When using this product diuretic effect may occur.", "Note:", "This statement can be removed from the label if a diuretic claim is included."]'::jsonb, '["Adults 18 years and older", "2 - 20 grams of dried or fresh root, per day (Blumenthal et al. 2000; Mills 1985; Grieve 1971; Wren 1907)", "Note:", "Solvents allowed for the method of preparation 