  ('mugwort-european', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=mugwort&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help stimulate the appetite (Bradley 2006; Williamson et al. 1988; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a stomachic) to aid digestion (Bradley 2006; Hoffmann 2003; Williamson et al. 1988; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a choleretic) to help increase bile flow (Bradley 2006; Wichtl 2004; Williamson et al. 1988)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Do not use if you are pregnant or breastfeeding (Brinker 2010; Blumenthal et al. 1998; Williamson et al. 1988).", "Stop use if hypersensitivity/allergy occurs (Brinker 2010; Wichtl 2004; Hoffmann 2003)."]'::jsonb, '["Adults 18 years and older", "Dry, Powdered, Non-Standardized Extracts (Dry extract", ", Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "0.2 - 2.4 grams of dried herb top, 3 times per day (Bradley 2006; Wichtl 2004; Hoffmann 2003).", "Note:", "Solvents allowed for the method of preparation \"Non-Standardized Extracts (Dry extract)\" as part of this monograph are ethanol and/or water only."]'::jsonb, 'imported-ogl-canada'),
  ('lamiaceae-pennyroyal', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=pennyroyal2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a stomachic) to aid digestion (Mills and Bone 2005; Hoffman 2003; Williamson et al. 1988; BHP 1983; Grieve 1971)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as a carminative) to help relieve indigestion/flatulent dyspepsia (Mills and Bone 2005; Hoffman 2003; Williamson et al. 1988; BHP 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as an antispasmodic) to help relieve intestinal colic (Mills and Bone 2005; Hoffman 2003; Williamson et al. 1988; BHP 1983; Grieve 1971)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have liver or kidney problems (Gardner and McGuffin 2013; Brinker 2010).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking acetaminophen (Brinker 2010).", "Do not use if you are pregnant or breastfeeding (Brinker 2010).", "No statement required."]'::jsonb, '["Adults 18 years and older", "Dry, Powdered, Non-Standardized Extracts (Dry extract", ", Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "3 – 12 grams of dried herb top, per day; Not to exceed 4 grams of dried herb top per single dose (Mills and Bone 2005; Williamson et al. 1988; BHP 1983; Grieve 1971).", "Note:", "Solvents allowed for the method of preparation \"Non-Standardized Extracts (Dry extract)\" as part of this monograph are ethanol and/or water only.", "Method of preparation:", "Tincture", "0.6 – 1.2 grams of dried herb top, per day (Mills and Bone 2005; Hoffman 2003)."]'::jsonb, 'imported-ogl-canada'),
  ('phaseolus-vulgaris', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=phaseolus.vulgaris2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Provides support for healthy (postprandial) glucose metabolism (within two hours after a meal) (Barrett and Udani 2011; Udani"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 2009; Vinson"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 2009; Boivin"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 1987; Layer"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 1986)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps improve (postprandial) glucose metabolism (within two hours after a meal) (Barrett and Udani 2011; Udani"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 2009; Vinson"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 2009; Boivin"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 1987; Layer"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 1986)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps reduce the (enzymatic) digestion of carbohydrates (Barrett and Udani 2011; Vinson"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 2009; Layer"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 1985; Boivin"}, {"section": "Use(s) or Purpose(s)", "text": "et al"}, {"section": "Use(s) or Purpose(s)", "text": ". 1987; Layer"}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are breastfeeding.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes (Buse 2000).", "Do not use if you are pregnant.", "No statement required."]'::jsonb, '["Adults 18 years and older", "Glucose metabolism; Carbohydrate digestion", "1.5 - 3 grams of white kidney bean extract per day, standardized to 3,000 AAIU", "1", "of alpha-amylase inhibitors, per gram of extract", "2", "(Barrett and Udani 2009; Udani et al. 2009; Vinson et al. 2009; Layer et al. 1985).", "Weight management", "1 gram of white kidney bean extract, three times per day, standardized to 3,000 AAIU", "1", "of alpha-amylase inhibitors per gram of extract (Udani et al. 2018; Grube et al 2014; Wu et al. 2010; Celleno et al. 2007; Udani and Singh 2007; Udani et al. 2004).", "Notes:", "1", "AAIU = alpha-amylase inhibiting units.", "2", "The potency quantity should be equal to 3,000 AAIU of alpha-amylase inhibitors per gram of extract. For example, if the quantity of the extract per dosage unit is listed as 500 mg, the quantity of alpha-amylase inhibitors should be 1,500 AAIU or if the quantity of the extract is 1,500 mg per dosage unit, the quantity of alpha-amylase inhibitors should be 4,500 AAIU, etc."]'::jsonb, 'imported-ogl-canada'),
  ('evening-primrose', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=primrose.onagre2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Source of essential fatty acids for the maintenance of good health (Brayfield and Cadart 2024; IOM"}, {"section": "Use(s) or Purpose(s)", "text": "2006)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of omega-6 fatty acids for the maintenance of good health (IOM 2006; Mills and"}, {"section": "Use(s) or Purpose(s)", "text": "Bone 2005; WHO 2002)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of linoleic acid (LA) for the maintenance of good health (IOM 2006; Mills and Bone"}, {"section": "Use(s) or Purpose(s)", "text": "2005; WHO 2002)."}]'::jsonb, '["No statement required."]'::jsonb, '["Adults 18 years and older", "Method of preparation:", "Non-standardized fixed oil", "1.3-6 grams of evening primrose oil, per day (Brayfield and Cadart 2024; IOM 2006; Mills and Bone", "2005; WHO 2002; Keen et al. 1993).", "Method of preparation:", "Standardized fixed oil", "1.3-6 grams of evening primrose oil, per day (Brayfield and Cadart 2024; IOM 2006; Mills and Bone", "2005; WHO 2002; Keen et al. 1993) standardized to:", "7-14% gamma-linolenic/gamolenic acid (GLA), and/or", "65-85% linoleic acid (LA).", "Note:", "The following potency information is considered as additional information and can be", "included on the label: XX% total omega-6 fatty acids"]'::jsonb, 'imported-ogl-canada'),
  ('nettle', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=stinging.nettle2&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Herb top"}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine as a diuretic (Mills and Bone 2005; ESCOP 2003; Bisset and Wichtl 2001; Blumenthal et al. 2000; Tilgner 1999; Bradley 1992; Wren 1907)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as supportive therapy to help relieve rheumatic complaints (Mills and Bone 2005; ESCOP 2003; Blumenthal et al. 2000; Bradley 1992)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as a nutritive tonic (Hoffman 2003; Tilgner 1999)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help relieve seasonal allergy symptoms (Mills and Bone 2005; Tilgner 1999)."}, {"section": "Use(s) or Purpose(s)", "text": "Root"}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help reduce difficulty in urination associated with the early stages of benign prostatic hyperplasia (BPH) (Bradley 2006; Mills and Bone 2005; ESCOP 2003; Hoffmann 2003; Blumenthal et al. 2000)."}]'::jsonb, '["All products except nutritive tonics", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Do not use if you are pregnant or breastfeeding (Brinker 2010; Barnes et al. 2007; Tilgner 1999).", "All products except those making only a diuretic claim", "When using this product diuretic effect may occur.", "Note:", "This statement can be removed from the label if a diuretic claim is included."]'::jsonb, '["Adults 18 years and older", ", Tincture, Fluid extract, Decoction, Decoction concentrate, Infusion, Infusion concentrate)", "Herb top", "1.2 - 18 grams of dried herb tops, per day (Mills and Bone 2005; ESCOP 2003; Hoffman 2003; Blumenthal et al. 2000; Bradley 1992)", "Root", "0.3 - 24 grams of dried root, per day (Bradley 2006; Mills and Bone 2005; ESCOP 2003; Hoffman 2003; Blumenthal et al. 2000)", "Note:", "Solvents allowed for the method of preparation \"Non-Standardized Extracts (Dry extract)\" as part of this monograph are ethanol and/or water only."]'::jsonb, 'imported-ogl-canada'),
  ('white-willow', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=white.wil.saule.bla&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine for short-term relief of lower back pain (EMA 2017)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to relieve minor joint pain (due to osteoarthritis) (EMA 2017, ESCOP 2003)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to relieve fever associated with the common cold (EMA 2017)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to relieve headache (EMA 2017)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have asthma or peptic ulcer disease (EMA 2017).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or products containing salicylates (e.g., acetylsalicylic acid or non-steroidal anti-inflammatory drugs) (EMA 2017).", "Do not use if you are pregnant or breastfeeding (EMA 2017; Brinker 2010; Wichtl 2004; ESCOP 2003; Barnes et al. 2002; Blumenthal et al. 2000).", "Do not use if you are allergic to salicylates (EMA 2017; Brinker 2010; Wichtl 2004, ESCOP 2003; Barnes et al. 2002; Blumenthal et al. 2000).", "When using this product you may experience gastrointestinal discomfort/disturbances (EMA 2017; Brinker 2010; Wichtl 2004; ESCOP 2003; Barnes et al. 2002; Blumenthal et al. 2000)"]'::jsonb, '["Adults 18 years and older", "Note:", "When ‘decoction’ or ‘infusion’ is listed as an acceptable method of preparation, ‘decoction concentrate’ or ‘infusion concentrate’ is also allowed. It also applies to standardized methods of preparation.", "3- 9 grams of dried (young branch) bark per day in divided doses: Not to exceed 3 grams per single dose (EMA 2017; ESCOP 2003; Barnes et al. 2002; Blumenthal et al. 2000)", "Extract providing up to 15% total salicin equivalent to 45 - 240 milligrams of total salicin per day in divided doses; Not to exceed 120 milligrams of salicin per single dose (EMA 2017; WHO 2009; Wichtl 2004; ESCOP 2003; Barnes et al. 2002; Blumenthal et al. 2000)"]'::jsonb, 'imported-ogl-canada'),
  ('cranberry', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-vaccinium-macrocarpon-aiton-fructus_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Indication 1) Traditional herbal medicinal product used for relief of symptoms of mild recurrent lower urinary tract infections such as burning sensation during urination and/or frequent 1 The declaration of the active substance(s) for an individual finished product should be in accordance with relevant herbal quality guidance. 2 Detailed specifications for the herbal substance shall be given by references to bibliographic sources in absence of a monograph in the European Pharmacopoeia, a national pharmacopoeia or national codex currently used officially in a Member State. European Union herbal monograph on Vaccinium macrocarpon Aiton, fructus EMA/HMPC/49135/2017 Page 3/7 urination in women, after serious conditions have been excluded by a medical doctor. Indication 2) Traditional herbal medicinal product used for prevention of recurrent uncomplicated lower urinary tract infections in women, after serious conditions have been excluded by a medical doctor. The product is a traditional herbal medicinal product for use in the specified indication exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to cranberry (Vaccinium macrocarpon Ait.) fruit. Patients with kidney disorders who experienced recurrent urinary tract infections require medical supervision. Concomitant use with tacrolimus and warfarin (see section 4.5 ‘Interactions with other medicinal products and other forms of interaction’).", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children and adolescents under 18 years of age is not recommended because data is not sufficient and medical advice should be sought. The use in men and pregnant women is not recommended because lower urinary tract symptoms in these populations require medical supervision. Cranberry concentrate has a high content of oxalate, and there may be an increased risk of stone formation in the urinary tract in patients with stone history. If the symptoms worsen or if complaints such as fever, dysuria, spasms, or blood in urine occur during the use of the medicinal product, a doctor or a qualified", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Cranberry juice and other cranberry products may potentiate the effect of warfarin and therefore concomitant use should be avoided (see section 4.3. ‘Contraindications’). Decreased tacrolimus serum levels have been reported from the concomitant use of cranberry juice and tacrolimus in a renal allografted patient. The concomitant use of cranberry preparations and tacrolimus should be avoided (see section 4.3. ‘Contraindications’).", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use No fertility data available. Safety during pregnancy and lactation has not been established. In absence of sufficient data, the use during pregnancy and lactation is not recommended."]'::jsonb, '["Well-established use Traditional use Posology Female adults and elderly Indication 1) 50-60 ml expressed juice 2 - 4 times daily Indication 2) 30 ml expressed juice once daily The use in children and adolescents under 18 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). The use in men is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use Indication 1) If the symptoms persist for more than 4 days during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Indication 2) No restriction. If the patient experience symptoms of urinary tract infection during the use of the medicinal product, a doctor or a qualified health care European Union herbal monograph on Vaccinium macrocarpon Aiton, fructus EMA/HMPC/49135/2017 Page 4/7 Well-established use Traditional use practitioner should be consulted. Method of administration Oral use."]'::jsonb, 'imported-ema-hmpc'),
  ('fraxinus-excelsior-herb', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-community-herbal-monograph-fraxinus-excelsior-l-or-fraxinus-angustifolia-vahl-folium_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Indication 1) Traditional herbal medicinal product used for relief of minor articular pain. Indication 2) 1 The declaration of the active substance(s) for an individual finished product should be in accordance with relevant herbal quality guidance. 2 The material complies with the Ph. Eur. monograph (ref.: 07/2012:1600). Community herbal monograph on Fraxinus excelsior L. or Fraxinus angustifolia Vahl, folium EMA/HMPC/239271/2011 Page 2/6 Traditional herbal medicinal product used to increase the amount of urine to achieve flushing of the urinary tract as an adjuvant in minor urinary complaints. The product is a traditional herbal medicinal product for use in specified indications exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance(s). Condition where a reduced fluid intake is recommended (e.g. severe cardiac or renal disease).", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children and adolescents under 18 years of age has not been established due to lack of adequate data. If the symptoms worsen during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Indication 1) Articular pain accompanied by swelling of joints, redness or fever should be examined by a doctor. Indication 2) If minor urinary tract complaints worsen and symptoms such as fever, dysuria, spasm, or blood in the urine occur during the use of medicinal product, a doctor or a qualified health care professional should be consulted. To ensure a", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported.", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. Community herbal monograph on Fraxinus excelsior L. or Fraxinus angustifolia Vahl, folium EMA/HMPC/239271/2011 Page 4/6 Well-established use Traditional use No fertility data available."]'::jsonb, '["3 Well-established use Traditional use Posology Adults and elderly Average daily dose: Herbal tea: 20 g of the comminuted herbal substance in 1000 ml of water as a decoction, divided in 2-3 single doses. Herbal tea: 10-30 g of the comminuted herbal substance in 1000 ml of boiling water as a herbal infusion, divided in 2-3 single doses. The use in children and adolescents under 18 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use Indication 1) If the symptoms persist longer than 4 weeks during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Indication 2) If the symptoms persist longer than 2 weeks during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Method of administration Oral use. 3 For guidance on herbal substance/herbal preparation administered as herbal tea or as infusion/decoction/macerate preparation, please"]'::jsonb, 'imported-ema-hmpc'),
  ('phaseolus-vulgaris', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-community-herbal-monograph-phaseolus-vulgaris-l-fructus-sine-semine_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Traditional herbal medicinal product used to increase the amount of urine to achieve flushing of the urinary tract as an adjuvant in minor urinary tract complaints. The product is a traditional herbal medicinal product for use in the specified indication exclusively based upon long-standing use. 2 The declaration of the active substance(s) for an individual finished product should be in accordance with relevant herbal quality guidance 3 The material complies with DAC 1986 Community herbal monograph on Phaseolus vulgaris L., fructus sine semine EMA/HMPC/317319/2012 Page 2/5"}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance.", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children and adolescents under 18 years of age is not recommended because of lack of data. If the symptoms worsen during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted.", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported. 4 For guidance on herbal substance/herbal preparation administered as herbal tea or as infusion/decoction/macerate preparation, please refer to the HMPC ‘Glossary on herbal teas’ (EMA/HMPC/5829/2010 Rev.1). Community herbal monograph on Phaseolus vulgaris L., fructus sine semine EMA/HMPC/317319/2012 Page 3/5", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["4 Well-established use Traditional use Posology Adults and elderly Single dose Herbal tea: 2.5 g of the comminuted herbal substance in 150 ml of boiling water as a herbal infusion, 2 - 6 times daily. The use in children and adolescents under 18 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use If the symptoms persist longer than 2 weeks during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Method of administration Oral use."]'::jsonb, 'imported-ema-hmpc'),
  ('sideritis', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-sideritis-scardica-griseb-sideritis-clandestina-bory-chaub-hayek-sideritis-raeseri-boiss-heldr-sideritis-syriaca-l-herba_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Indication 1) Traditional herbal medicinal product used for the 2 The declaration of the active substance(s) for an individual finished product should be in accordance with relevant herbal quality guidance. 3 Detailed specifications for the herbal substance shall be given by references to bibliographic sources in absence of a monograph in the European Pharmacopoeia, a national pharmacopoeia or national codex currently used officially in a Member State European Union herbal monograph on Sideritis scardica Griseb.; Sideritis clandestina (Bory & Chaub.) Hayek; Sideritis raeseri Boiss. & Heldr.; Sideritis syriaca L., herba EMA/HMPC/39453/2015 Page 3/7 relief of cough associated with cold. Indication 2) Traditional herbal medicinal product used for the relief of mild gastrointestinal discomfort. The product is a traditional herbal medicinal product for use in specified indications exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance and to other plants of the Lamiaceae (Labiatae) family.", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children and adolescents under 18 years of age has not been established due to lack of adequate data. If the symptoms worsen during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted.", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["Well-established use 4 Traditional use Posology Adults and elderly Indication 1) and 2) Single dose: Herbal tea: 2-4 g of the comminuted herbal substance in 150-200 ml of water as a herbal infusion 2-3 times daily Daily dose up to 12 g The use in children and adolescents under 18 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use Indication 1) If the symptoms persist longer than 1 week, during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Indication 2) If the symptoms persist longer than 2 weeks during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Method of administration Oral use 4 For guidance on herbal substance/herbal preparation administered as herbal tea or as infusion/decoction/macerate preparation, please refer to the HMPC ‘Glossary on herbal teas’ (EMA/HMPC/5829/2010 Rev.1). European Union herbal monograp"]'::jsonb, 'imported-ema-hmpc'),
  ('fumitory-herb', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-fumaria-officinalis-l-herba-revision-1_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Traditional herbal medicinal product used for the relief of digestive disturbances, such as feelings of fullness, slow digestion and flatulence. The product is a traditional herbal medicinal product for use in the specified indications exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance.", "Warnings & precautions (4.4): for use Well-established use Traditional use Due to possible stimulation on bile secretion Fumariae herba is not recommended in case of obstruction of the bile duct, cholangitis, liver disease, gallstones and any other biliary disease. For a) The use in children under 12 years of age has not been established due to lack of adequate data. For b), c), d), e) and f) The use in children and adolescents under 18 European Union herbal monograph on Fumaria officinalis L., herba EMA/HMPC/367011/2021 Page 5/7 Well-established use Traditional use years of age has not been established due to lack of adequate data. If the symptoms worsen during the use o", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported.", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["3 Well-established use Traditional use Posology Adolescents, Adults and Elderly a) Comminuted herbal substance Single dose: Herbal tea: 2 g of comminuted herbal substance in 250 ml of boiling water or 1.6 g of comminuted herbal substance in 150 ml of boiling water as herbal infusion Daily dose: 4.8-6.4 g daily, divided in 3-4 doses Adults and Elderly b) Powdered herbal substance Single dose: 220 mg Daily dose: up to 1100 mg c) Dry extract Single dose: 250 mg Daily dose: up to 1000 mg d) Liquid extract Single dose: 0.5-2 ml Daily dose: 2-4 ml 3 For guidance on herbal substance/herbal preparation administered as herbal tea or as infusion/decoction/macerate preparation, please refer to the HMPC ‘Glossary on herbal teas’ (EMA/HMPC/5829/2010 Rev.1). European Union herbal monograph on Fumaria officinalis L., herba EMA/HMPC/367011/2021 Page 4/7 Well-established use Traditional use e) Tincture Single dose: 0.5-1 ml Daily dose: 1-4 ml f) Juice of fresh plant Daily dose: 3.5-4 g For a) The use i"]'::jsonb, 'imported-ema-hmpc'),
  ('echinacea-angustifolia', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-community-herbal-monograph-echinacea-angustifolia-dc-radix_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Traditional herbal medicinal product for supportive treatment of common cold. The product is a traditional herbal medicinal product for use in the specified indication exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance(s) and to other plants of the Asteraceae (Compositae) family.", "Warnings & precautions (4.4): for use Well-established use Traditional use Not recommended in cases of progressive systemic diseases such as tuberculosis, diseases of the white blood cells system, collagenoses, multiple sclerosis, AIDS, HIV infections and other immune diseases. If the symptoms worsen or high fever occurs during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. There is a possible risk of allergic reactions in sensitive individuals. Those patients should consult their doctor before using Echinacea. There is a possible risk of anaphylactic reactions in atopic patients. Atopic patients should consult thei", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported.", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. No fertility data available. Community herbal monograph on Echinacea angustifolia DC., radix EMA/HMPC/688216/2008 Page 6/6"]'::jsonb, '["Well-established use Traditional use Posology Adolescents, adults and elderly Single dose Herbal tea: 1 g of the comminuted herbal substance in 150 ml of boiling water as an infusion 3 times daily. Time of infusion: at least 10 minutes 1 g of the comminuted herbal substance in 150 ml of water as a decoction 3 times daily. Time of decoction:10 minutes Powdered herbal substance: 500 mg, up to 3 times daily. Tincture: 1-2 ml, three times daily. Liquid extract: 0.25 -1 ml, three times daily. The use in children under 12 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use The therapy should start at first signs of common cold. If the symptoms persist longer than 10 days during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Method of administration Oral use. Community herbal monograph on Echinacea angustifolia DC., radix EMA/HMPC/688216/2008 Page 5/6"]'::jsonb, 'imported-ema-hmpc'),
  ('misai-kucing', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/european-union-herbal-monograph-orthosiphon-aristatus-blume-miq-var-aristatus-folium-revision-1_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Traditional herbal medicinal product used to increase the amount of urine to achieve flushing of the urinary tract as an adjuvant in minor urinary tract complaints. The product is a traditional herbal medicinal product for use in the specified indication exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance. Conditions where a reduced fluid intake is recommended (e.g. severe cardiac or renal disease).", "Warnings & precautions (4.4): for use). Duration of use If the symptoms persist longer than 2 weeks during the use of the medicinal product a doctor or a qualified health care practitioner should be consulted. Method of administration Oral use. To ensure an increase of the amount of urine, adequate fluid intake is required during treatment. 4.3. Contraindications Well-established use Traditional use Hypersensitivity to the active substance. Conditions where a reduced fluid intake is recommended (e.g. severe cardiac or renal disease). 4.4. Special warnings and precautions for use Well-established use Traditional use The use in children and adolescents under 18 years of age", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported.", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["Well-established use Traditional use Posology Adults and Elderly a) Herbal tea: 2-3 g comminuted herbal substance in 150 ml of boiling water as a herbal infusion Daily dose: 6-12 g b) Powdered herbal substance Single dose: 500-750 mg Daily dose: 1000-1500 mg c) Liquid extract (DER 1:1), extraction solvent ethanol 25% m/m Single dose: 2 g Daily dose: 2-4 g d) Dry extract (DER 5-7:1), extraction solvent water Single dose: 360 mg Daily dose: 1080-1440 mg e) Dry extract (DER 8-12:1), extraction solvent ethanol 60% V/V Single dose: 200-400 mg European Union herbal monograph on Orthosiphon aristatus (Blume) Miq. var. aristatus, folium EMA/HMPC/486551/2020 Page 4/7 Well-established use Traditional use Daily dose: 600-1200 mg f) Dry extract (DER 7-8:1), extraction solvent ethanol 70% V/V Single dose: 280 mg Daily dose: 840 mg g) Dry extract (DER 5-7:1), extraction solvent ethanol 30% V/V Single dose: 200 mg Daily dose: 400 mg The use in children and adolescents under 18 years of age is not rec"]'::jsonb, 'imported-ema-hmpc'),
  ('eschscholzia-californica-herb', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-eschscholzia-californica-cham-herba_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "1) Traditional herbal medicinal product for relief of mild symptoms of mental stress. 2) Traditional herbal medicinal product to aid sleep. The product is a traditional herbal medicinal product for use in specified indications exclusively 1 The declaration of the active substance(s) for an individual finished product should be in accordance with relevant herbal quality guidance. 2 Detailed specifications for the herbal substances shall be given by references to bibliographic sources in absence of a monograph in the European Pharmacopoeia, a national pharmacopoeia or national codex currently used officially in a Member State. European Union herbal monograph on Eschscholzia californica Cham., herba EMA/HMPC/680372/2013 Page 2/5 based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance/s. European Union herbal monograph on Eschscholzia californica Cham., herba EMA/HMPC/680372/2013 Page 3/5", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children and adolescents under 18 years of age has not been established due to lack of adequate data. If the symptoms worsen during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted.", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported.", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["Well-established use Traditional use Posology Posology Adults, Elderly Indication 1) Powdered herbal substance: Single dose: 480-600 mg Daily dose: 960-1500 mg Indication 2) Powdered herbal substance: Single dose: 480-600 mg Daily dose: 960–1500 mg One single dose with dinner and another single dose 30-60 min before bedtime. The use in children and adolescents under 18 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use If the symptoms persist longer than 2 weeks during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Method of administration Oral use."]'::jsonb, 'imported-ema-hmpc'),
  ('ginseng', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-panax-ginseng-camey-radix-revision-1_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Traditional herbal medicinal product for symptoms of asthenia such as fatigue and weakness. The product is a traditional herbal medicinal product for use in the specified indication exclusively based upon long-standing use. European Union herbal monograph on Panax ginseng C.A.Mey., radix EMA/HMPC/27744/2023 Page 4/10"}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance.", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children and adolescents under 18 years of age has not been established due to lack of adequate data. If the symptoms worsen during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. For extracts containing ethanol, the appropriate labelling for ethanol, taken from the ‘Guideline on excipients in the label and European Union herbal monograph on Panax ginseng C.A.Mey., radix EMA/HMPC/27744/2023 Page 7/10 Well-established use Traditional use package leaflet of medicinal products for human use’, must be included.", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported.", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["3 Well-established use Traditional use Posology Adults and elderly White ginseng: a) Comminuted herbal subs