  ('betula-pendula-bark', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-betula-pendula-roth-betula-pubescens-ehrh-folium_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Traditional herbal medicinal product to increase the amount of urine to achieve flushing of the urinary tract as an adjuvant in minor urinary complaints. The product is a traditional herbal medicinal product for use in the specified indication exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance or to birch pollen. Conditions where a reduced fluid intake is recommended (e.g. severe cardiac or renal disease).", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children under 12 years of age has not been established due to lack of adequate data. If complaints or symptoms such as fever, dysuria, spasms or blood in urine occur during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. For extracts containing ethanol, the appropriate labelling for ethanol, taken from the ‘Guideline on excipients in the label and package leaflet of medicinal products for human use’, must be included.", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported. European Union herbal monograph on Betula pendula Roth and/or Betula pubescens Ehrh. as well as hybrids of both species, folium EMA/HMPC/573241/2014 Page 5/7", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In the absence of sufficient data, the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["3 Well-established use Traditional use Posology Adolescents, adults and elderly a) Comminuted herbal substance Herbal tea: 2-3 g of the comminuted herbal substance in 150 ml of boiling water as a herbal infusion up to 4 times daily b) Powdered herbal substance Single dose: 650 mg, 2 times daily c) Dry extract: Single dose: 0.25–1 g, 4 times daily d) Liquid extract: Single dose: 15 ml, 2-3 times daily e) Liquid extract stabilized: Single dose: 2.5 ml, 3 times daily The use in children under 12 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use The herbal preparations are traditionally used 3 For guidance on herbal substance/herbal preparation administered as herbal tea or as infusion/decoction/macerate preparation, please refer to the HMPC ‘Glossary on herbal teas’ (EMA/HMPC/5829/2010 Rev.1). European Union herbal monograph on Betula pendula Roth and/or Betula pubescens Ehrh. as well as hybrids of both species, folium EMA/HMPC/5"]'::jsonb, 'imported-ema-hmpc'),
  ('boldo-leaf', 'European Medicines Agency (HMPC)', 'EMA public document — reproduced with attribution', 'European Medicines Agency (EMA), Committee on Herbal Medicinal Products (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-peumus-boldus-molina-folium_en.pdf', '[{"section": "4.1 Therapeutic indications", "text": "Traditional herbal medicinal product used for symptomatic relief of dyspepsia and mild 1 The declaration of the active substance(s) for an individual finished product should be in accordance with relevant herbal quality guidance. 2 The material complies with the Ph. Eur. monograph (ref.: 1396) European Union herbal monograph on Peumus boldus Molina, folium EMA/HMPC/453725/2016 Page 3/6 spasmodic disorders of the gastrointestinal tract. The product is a traditional herbal medicinal product for use in the specified indication exclusively based upon long-standing use."}]'::jsonb, '["Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance(s). Obstruction of bile duct, cholangitis, liver disease, gallstones and any other biliary disorders that require medical supervision and advice. 3 For guidance on herbal substance/herbal preparation administered as herbal tea or as infusion/decoction/macerate preparation, please refer to the HMPC ‘Glossary on herbal teas’ (EMA/HMPC/5829/2010 Rev.1). European Union herbal monograph on Peumus boldus Molina, folium EMA/HMPC/453725/2016 Page 4/6", "Warnings & precautions (4.4): for use Well-established use Traditional use The use in children and adolescents under 18 years of age has not been established due to lack of adequate data and because of concerns requiring medical advice. If the symptoms worsen during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted.", "Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use None reported", "Fertility, pregnancy & lactation (4.6): Well-established use Traditional use Safety during pregnancy and lactation has not been established. In view of the pre-clinical safety data (see section 5.3), the use during pregnancy and lactation is not recommended. No fertility data available."]'::jsonb, '["Well-established use 3 Traditional use Posology Adults and elderly a) Comminuted herbal substance Herbal tea: 1–2 g of the comminuted herbal substance in 150 ml of boiling water as a herbal infusion, 2-3 times daily b) Dry extract (DER 5:1) extraction solvent water Single dose: 200-400 mg, 2 times daily Daily dose: 400-800 mg The use in children and adolescents under 18 years of age is not recommended (see section 4.4 ‘Special warnings and precautions for use’). Duration of use If the symptoms persist longer than 2 weeks during the use of the medicinal product, a doctor or a qualified health care practitioner should be consulted. Method of administration Oral use"]'::jsonb, 'imported-ema-hmpc'),
  ('sophora-japonica-quercetin-phosphatidylcholine-complex', 'LiverTox', 'public-domain-us-gov', 'NIDDK LiverTox (National Institutes of Health) — Public Domain.', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Quercetin/', '[]'::jsonb, '["Likelihood score: E (unlikely cause of clinically apparent liver injury).", "Quercetin supplements have not been linked serum aminotransferase elevations during therapy, although there have been few focused studies of its hepatic safety. Furthermore, there have been no published reports of clinically apparent liver injury attributable to quercetin. Indeed, many in vitro and in vivo studies have shown that quercetin protects against hepatic injury caused by drugs and toxins including acetaminophen and cancer chemotherapeutic agents. These hepatoprotective effects have not been demonstrated in prospective clinical trials in humans."]'::jsonb, '[]'::jsonb, 'imported-livertox-nxml'),
  ('resveratrol-source', 'LiverTox', 'public-domain-us-gov', 'NIDDK LiverTox (National Institutes of Health) — Public Domain.', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Resveratrol/', '[]'::jsonb, '["Likelihood score: E (unlikely cause of clinically apparent liver injury).", "There have been multiple trials of resveratrol in human subjects, but the dose regimen and duration of therapy has varied greatly and many trials lacked information on adverse events, ALT elevations, and hepatotoxicity. Nevertheless, in most studies there was no mention of serum ALT elevations or only rare and mild-to-moderate increases that were asymptomatic and resolved rapidly upon stopping therapy. However, in studies using high doses of resveratrol (1.5 to 3.0 grams daily), average serum ALT and AST levels rose slightly during therapy and promptly fell into the normal range with stopping. There were, however, no instances of serum ALT elevations with jaundice or symptoms. Furthermore, despite widespread clinical use, there have been no published reports of clinically apparent liver injury attributed to resveratrol. In large case series and nationwide registries on herbal induced liver injury, resveratrol is not listed as a cause. Thus, hepatotoxicity due to resveratrol must be rare, if it occurs at all."]'::jsonb, '[]'::jsonb, 'imported-livertox-nxml'),
  ('nettle', 'LiverTox', 'public-domain-us-gov', 'NIDDK LiverTox (National Institutes of Health) — Public Domain.', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/StingingNettle/', '[]'::jsonb, '["Likelihood score: E (unlikely cause of clinically apparent liver injury).", "In multiple short- and long-term clinical trials of different preparations of stinging nettle extracts, adverse side effects were described as uncommon and minimal with no mention of either hepatotoxicity or ALT elevations. Few prospective studies included monitoring of liver tests, but those that did reported no change in serum aminotransferase levels. Despite widespread use, there have been no published reports of serum enzyme elevations or clinically apparent liver injury attributable to stinging nettle root or leaf extracts.", "Hepatotoxicity from extracts of stinging nettle roots, leaves and flowering parts has not been reported.", "Other names: Nettle, Common Nettle, Stinger, Bichu, Ortie, Urtica."]'::jsonb, '[]'::jsonb, 'imported-livertox-nxml'),
  ('ginseng', 'LiverTox', 'public-domain-us-gov', 'NIDDK LiverTox (National Institutes of Health) — Public Domain.', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Ginseng/', '[]'::jsonb, '["Likelihood score: E (by itself, unlikely cause of clinically apparent liver injury).", "Despite wide spread use, ginseng by itself has not been linked to liver injury, either in the form of transient serum enzyme elevations or clinically apparent acute liver injury. Indeed, ginseng is sometimes used to treat acute or chronic liver injury, although its efficacy and safety in this situation have not been proven. Nevertheless, ginseng has been reported to affect cytochrome P450 activity and cause significant herb-drug interactions that can lead to adverse events including liver injury. In vitro studies have found that different gensinosides have different effects on cytochrome P450 activity, and some may inhibit CYP 3A4 sufficiently to affect the metabolism of other drugs, increasing or decreasing their activity. Thus, different ginseng preparations may exhibit varying degrees of herb-drug interaction. Liver injury has been reported to develop 1 to 3 months after starting ginseng in patients who previously tolerated the potentially toxic agent (imatinib, raltegravir) without liver injury and who later tolerated restarting the medication without concurrent ginseng use."]'::jsonb, '[]'::jsonb, 'imported-livertox-nxml'),
  ('frangula-purshiana', 'LiverTox', 'public-domain-us-gov', 'NIDDK LiverTox (National Institutes of Health) — Public Domain.', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Cascara/', '[]'::jsonb, '["Use of cascara in the recommended doses for a limited period of time has been associated with few side effects, most of which are mild and transient. With longer term use of high doses of cascara, however, adverse events have been described including several cases of clinically apparent liver injury. The time to onset of liver injury has varied from a few days to 2 months of use, and the pattern of serum enzyme elevations varied from hepatocellular to cholestatic. The liver injury ranged from mild to severe, but usually resolved rapidly with discontinuation. Immunoallergic features and autoimmune markers were not prominent or consistently present in the published cases.", "Liver injury from long term cascara use is rare and most cases have been self-limited and rapidly reversible upon stopping the laxative. However, severe cases with acute liver failure and development of ascites and portal hypertension have been described. There is no evidence of cross sensitivity to hepatic damage with other laxatives. Restarting cascara has been associated with recurrence of liver injury and should be avoided.", "Other drugs in the Anthraquinone Subclass: Senna"]'::jsonb, '[]'::jsonb, 'imported-livertox-nxml')
)
INSERT INTO public.herb_monograph_sources (
  herb_slug, source, licence, attribution, url, claims, safety, doses, generation_method, retrieved_at
)
SELECT
  s.herb_slug, s.source, s.licence, s.attribution, s.url, s.claims, s.safety, s.doses, s.generation_method, CURRENT_DATE
FROM src s
JOIN public.herbs h ON h.slug = s.herb_slug AND h.is_published = true
ON CONFLICT (herb_slug, source) DO NOTHING;
